CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, xp INTEGER NOT NULL DEFAULT 0 CHECK(xp>=0), coins INTEGER NOT NULL DEFAULT 0 CHECK(coins>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS levels (id INTEGER PRIMARY KEY, name TEXT NOT NULL, xp_required INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS concepts (id TEXT PRIMARY KEY, title TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS market_events (id TEXT PRIMARY KEY, title TEXT NOT NULL, event_date DATE, source_url TEXT NOT NULL, verified BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, content JSONB NOT NULL, concept_id TEXT REFERENCES concepts(id), event_id TEXT REFERENCES market_events(id), published BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS daily_challenges (day DATE PRIMARY KEY, question_ids JSONB NOT NULL CHECK(jsonb_array_length(question_ids)=10));
CREATE TABLE IF NOT EXISTS attempts (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, question_id TEXT NOT NULL REFERENCES questions(id), option_id TEXT NOT NULL, correct BOOLEAN NOT NULL, xp INTEGER NOT NULL, coins INTEGER NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('daily','unlimited')), day DATE NOT NULL, at TIMESTAMPTZ NOT NULL, duration INTEGER NOT NULL, category TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS unique_daily_attempt ON attempts(user_id,question_id,day) WHERE mode='daily';
ALTER TABLE attempts ADD COLUMN IF NOT EXISTS difficulty TEXT NOT NULL DEFAULT 'Beginner';
CREATE INDEX IF NOT EXISTS attempts_user ON attempts(user_id,at);
CREATE TABLE IF NOT EXISTS xp_transactions (attempt_id BIGINT PRIMARY KEY REFERENCES attempts(id), user_id UUID NOT NULL REFERENCES users(id), amount INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS historical_prices (provider TEXT NOT NULL, series TEXT NOT NULL, date DATE NOT NULL, value NUMERIC NOT NULL, fetched_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(provider,series,date));
CREATE TABLE IF NOT EXISTS case_studies (id TEXT PRIMARY KEY, title TEXT NOT NULL, stages JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS achievements (id TEXT PRIMARY KEY, title TEXT NOT NULL, criteria JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS user_achievements (user_id UUID REFERENCES users(id), achievement_id TEXT REFERENCES achievements(id), earned_at TIMESTAMPTZ DEFAULT NOW(), PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS reactions (type TEXT PRIMARY KEY, provider TEXT NOT NULL, asset TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TIMESTAMPTZ DEFAULT NOW());
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
ALTER TABLE users ADD COLUMN IF NOT EXISTS age_confirmed_at TIMESTAMPTZ;
ALTER TABLE attempts ADD COLUMN IF NOT EXISTS confidence INTEGER CHECK (confidence BETWEEN 0 AND 100);
CREATE TABLE IF NOT EXISTS event_runs (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_id TEXT NOT NULL, subject TEXT NOT NULL CHECK(subject IN ('index','mix','stock')), mix JSONB, plan JSONB NOT NULL, seed INTEGER NOT NULL, blind BOOLEAN NOT NULL DEFAULT FALSE, day INTEGER NOT NULL DEFAULT 0, decisions JSONB NOT NULL DEFAULT '[]', reflection TEXT NOT NULL DEFAULT '', summary JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), completed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS event_runs_user ON event_runs(user_id, created_at);
